import inspect

class Base:
    def __getattr__(self, attr):
        # mimic new logic
        try:
            descr = inspect.getattr_static(self, attr)
        except AttributeError:
            descr = None
        else:
            if hasattr(descr, '__get__'):
                return descr.__get__(self, type(self))
        raise AttributeError(f"{type(self).__name__} has no {attr}")

class C(Base):
    @property
    def prop(self):
        return self.random_attr

try:
